const MODES={
  build:{name:'Twin 생성',english:'DATA FOUNDATION',description:'소비 이력을 연결하고, 시뮬레이션의 기준이 될 금융 상태를 정의하세요.',icon:'upload'},
  forecast:{name:'미래 예측',english:'FUTURE FORECAST',description:'지금의 금융 패턴이 이어질 때, 앞으로의 현금과 소비를 계산합니다.',icon:'chart',index:'01'},
  what_if:{name:'What-if 비교',english:'SCENARIO BRANCH',description:'소비·소득 조건을 바꿔, 현재 행동과 다른 미래를 나란히 비교합니다.',icon:'branch',index:'02'},
  goal:{name:'목표 가능성',english:'GOAL FEASIBILITY',description:'목표 시점의 가용 현금과 자금 부족을 함께 고려해 가능성을 계산합니다.',icon:'target',index:'03'},
  risk:{name:'위험 분석',english:'RISK ANALYSIS',description:'계좌 잔액 부족, 예산 초과, 외부 충격에 취약한 지점을 확인합니다.',icon:'shield',index:'04'},
  optimize:{name:'행동 최적화',english:'ACTION OPTIMIZATION',description:'목표와 위험 조건을 만족하는 후보 중 소비 감축이 가장 작은 안을 찾습니다.',icon:'sliders',index:'05'}
};
const PATHS={upload:'M12 16V3m-5 5 5-5 5 5M4 15v5h16v-5',chart:'M4 4v16h17M7 14l4-4 4 2 5-7',branch:'M6 4v16m0-11c0 5 12 0 12 6v5M6 4l-2 2m2-2 2 2M18 20l-2-2m2 2 2-2',target:'M21 12a9 9 0 1 1-9-9m5 9a5 5 0 1 1-5-5m0 5 9-9m-5 0h5v5',shield:'M12 3 4 6v6c0 4 8 9 8 9s8-5 8-9V6zM8 12l3 3 5-6',sliders:'M5 3v8m0 5v5M12 3v3m0 5v10m7-18v10m0 5v3M2 11h6m1-5h6m1 7h6',arrow:'M4 12h16m-6-6 6 6-6 6',play:'m8 4 12 8-12 8z',code:'m8 6-6 6 6 6m8-12 6 6-6 6m-3-15-2 18',check:'M5 12l4 4L19 6',download:'M12 3v12m-5-5 5 5 5-5M4 17v4h16v-4',copy:'M8 8h13v13H8zM16 8V3H3v13h5',refresh:'M20 8a8 8 0 1 0 0 8M20 3v5h-5',plus:'M12 5v14M5 12h14',trash:'M4 6h16M9 6V3h6v3M6 6l1 15h10l1-15M10 10v7m4-7v7',stop:'M5 5h14v14H5z',info:'M12 11v6m0-10v1M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0',file:'M6 3h8l4 4v14H6zM14 3v5h5M9 12h6m-6 4h6',wallet:'M3 6h17v14H3zM3 6V4h14M15 11h6v5h-6z',close:'m6 6 12 12M6 18 18 6'};
const icon=n=>`<svg class="icon" viewBox="0 0 24 24" aria-hidden="true"><path d="${PATHS[n]||PATHS.info}"/></svg>`;
const main=document.querySelector('#main');
const clone=x=>JSON.parse(JSON.stringify(x));
const pretty=x=>JSON.stringify(x,null,2);
const state={config:null,twins:[],activeId:'',active:null,route:'build',requests:{},editors:{},raw:{},outputs:{},tabs:{},busy:null,error:null,
 build:{upload:null,profile:null,name:'',asOf:'',type:'history',snapshotText:'',manual:null,result:null,isDemo:false}};
let toastTimer;
function toast(message,error=false){const el=document.querySelector('#toast');el.textContent=message;el.classList.toggle('error',error);el.hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.hidden=true,4500);}
function errorMessage(e){return `${e.message||'요청에 실패했습니다.'}${e.code?' ['+e.code+']':''}${e.details?.path?.length?' · '+e.details.path.join('.') : ''}`;}
async function api(url,options={}){
 const headers={...(options.headers||{})};if(options.method&&!['GET','HEAD'].includes(options.method))headers['X-Workbench-Token']=state.config?.token||'';
 if(options.body&&!(options.body instanceof FormData)&&typeof options.body!=='string'){headers['Content-Type']='application/json';options.body=JSON.stringify(options.body);}
 let response;try{response=await fetch(url,{...options,headers,cache:'no-store'});}catch{throw Object.assign(new Error('서버에 연결할 수 없습니다. START.bat 실행 창을 확인하세요.'),{code:'NETWORK_ERROR'});}
 const value=await response.json().catch(()=>({error:{message:'서버 응답을 읽지 못했습니다.',code:'INVALID_RESPONSE'}}));
 if(!response.ok||value.status==='error')throw Object.assign(new Error(value.error?.message||'요청 실패'),value.error||{});
 return value;
}
function download(value,name,type='application/json'){const data=typeof value==='string'?value:pretty(value);const url=URL.createObjectURL(new Blob([data],{type}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
async function copyText(text){try{await navigator.clipboard.writeText(text);}catch{const el=document.createElement('textarea');el.value=text;document.body.append(el);el.select();const ok=document.execCommand('copy');el.remove();if(!ok)throw new Error('복사에 실패했습니다. JSON 파일을 저장하세요.');}toast('클립보드에 복사했습니다.');}
function getAt(object,path){return path.split('.').reduce((o,k)=>o?.[k],object);}
function setAt(object,path,value){const keys=path.split('.');let obj=object;keys.slice(0,-1).forEach(k=>{obj[k]??={};obj=obj[k];});const key=keys.at(-1);if(value===undefined)delete obj[key];else obj[key]=value;}
function numericField(label,path,value,{unit='',min=0,max=1e12,step=1,hint='',scale=1,required=true,type='number'}={}){
 const shown=value===undefined||value===null?'':Math.round(value*scale*1e8)/1e8;
 return `<label class="field"><span>${esc(label)}</span><div class="input-unit"><input data-path="${esc(path)}" data-scale="${scale}" type="${type}" value="${esc(shown)}" min="${min}" max="${max}" step="${step}" ${required?'required':''} ${unit?'aria-label="'+esc(label)+' ('+esc(unit)+')"':''}>${unit?`<em>${esc(unit)}</em>`:''}</div>${hint?`<small>${esc(hint)}</small>`:''}</label>`;
}
function textField(label,path,value,{hint='',placeholder=''}={}){return `<label class="field"><span>${esc(label)}</span><input data-path="${esc(path)}" type="text" value="${esc(value??'')}" placeholder="${esc(placeholder)}">${hint?`<small>${esc(hint)}</small>`:''}</label>`;}
function section(index,title,body){return `<section class="form-section"><div class="form-section-title"><span class="index-pill">${index}</span>${title}</div>${body}</section>`;}
function fixedRules(){return (state.active?.summary?.recurring_rules||[]).filter(r=>r.fixed_group);}
function fixedOverrideFields(scenario,prefix){
 const rules=fixedRules(),overrides=Array.isArray(scenario.fixed_overrides)?scenario.fixed_overrides:[];
 const rows=overrides.map((o,i)=>{const current=rules.find(r=>r.rule_id===o.rule_id);const options=current||rules.length?rules.map(r=>`<option value="${esc(r.rule_id)}" ${r.rule_id===o.rule_id?'selected':''}>${esc(r.rule_id)} · ${esc(r.fixed_group||'')} · ${Number(r.expected_amount_krw||0).toLocaleString()}원</option>`).join(''):`<option value="${esc(o.rule_id||'')}">${esc(o.rule_id||'알 수 없는 규칙')}</option>`;return `<div class="repeat-card spaced"><div class="row-head"><span>고정 일정 ${i+1}</span><button type="button" class="btn ghost" data-action="remove-override" data-index="${i}">${icon('trash')}</button></div><div class="fields"><label class="field"><span>반복 규칙</span><select data-path="${prefix}.fixed_overrides.${i}.rule_id" required>${options||'<option value="">고정 규칙 없음</option>'}</select></label>${numericField('발생 금액',`${prefix}.fixed_overrides.${i}.amount_krw`,o.amount_krw??current?.expected_amount_krw,{unit:'원',min:0,max:1e12,step:1})}</div></div>`;}).join('');
 return `<details class="disclosure"><summary>고정지출 규칙 금액 교체 · ${overrides.length}건</summary><p class="small muted">활성 Twin의 고정지출 반복 규칙만 선택합니다. 교체 금액은 시뮬레이션에만 적용됩니다.</p>${rows||'<p class="small muted">선택한 고정지출 반복 규칙이 없습니다.</p>'}<button type="button" class="btn spaced" data-action="add-override" ${!rules.length||overrides.length>=100?'disabled':''}>${icon('plus')} 규칙 교체 추가</button></details>`;
}
function renderNav(){document.querySelector('#nav').innerHTML=Object.entries(MODES).map(([key,m],i)=>`${i===1?'<div class="nav-caption">SIMULATION MODES</div>':''}<a class="nav-item ${state.route===key?'active':''}" href="#/${key}" ${state.route===key?'aria-current="page"':''}>${icon(m.icon)}<span>${m.name}</span>${m.index?`<span class="nav-number">${m.index}</span>`:''}</a>`).join('');document.querySelector('#crumb').textContent=MODES[state.route].name;}
function renderActive(){const el=document.querySelector('#active-twin');el.innerHTML='<option value="">Twin 선택</option>'+state.twins.map(t=>`<option value="${t.id}" ${state.activeId===t.id?'selected':''}>${esc(t.name)} · ${esc(t.as_of)}</option>`).join('');el.disabled=Boolean(state.busy);}
function routeFromHash(){const key=location.hash.replace(/^#\/?/,'').split('/')[0];return MODES[key]?key:'build';}
function heading(){let m=MODES[state.route];return `<div class="page-heading"><div><div class="eyebrow">${m.english}</div><h1>${state.route==='build'?'나의 금융 Twin 만들기':m.name}</h1><p>${m.description}</p></div><span class="tag">${state.route==='build'?'CSV → DIGITAL TWIN':`MODE ${m.index} / 05`}</span></div>`;}
function globalError(){return state.error?`<div class="note danger inline-error" role="alert">${esc(state.error)} <button class="btn ghost" data-action="dismiss-error">닫기</button></div>`:'';}
function busyBanner(){return state.busy?`<div class="busy-banner" role="status"><span>진행 중 · ${esc(state.busy.label)} <span id="global-elapsed">0.0</span>초</span><button class="btn danger" data-action="cancel-job" ${!state.busy.id?'disabled':''}>${icon('stop')} 작업 취소</button></div>`:'';}
function render(){renderNav();renderActive();main.innerHTML=heading()+globalError()+busyBanner()+(state.route==='build'?buildPage():modePage());if(state.route!=='build')renderOutput();}
function profileArt(){return `<svg class="profile-art" viewBox="0 0 300 130" role="img" aria-label="거래 데이터와 금융 Twin 연결 구조"><path d="M53 26H90Q105 26 105 65H146M53 65H146M53 104H90Q105 104 105 65M178 65h30q16 0 16-32h28m-44 32q16 0 16 33h28" stroke="currentColor" stroke-opacity=".35" fill="none"/><rect x="16" y="11" width="40" height="29" rx="7" fill="currentColor" opacity=".09"/><rect x="16" y="50" width="40" height="29" rx="7" fill="currentColor" opacity=".09"/><rect x="16" y="89" width="40" height="29" rx="7" fill="currentColor" opacity=".09"/><path d="M27 26h18M27 65h18M27 104h18" stroke="currentColor" opacity=".65"/><circle cx="161" cy="65" r="29" fill="currentColor" opacity=".07"/><circle cx="161" cy="65" r="21" fill="none" stroke="currentColor" opacity=".8"/><path d="m149 65 8 8 16-16" stroke="currentColor" fill="none" stroke-width="2"/><circle cx="257" cy="33" r="7" fill="currentColor" opacity=".6"/><circle cx="257" cy="98" r="7" fill="currentColor" opacity=".25"/></svg>`;}
function buildPage(){const b=state.build,p=b.profile;return `
 <div class="steps"><span class="current"><b>01</b> 데이터 연결</span><i></i><span class="${p?'current':''}"><b>02</b> 상태 정의</span><i></i><span class="${b.result?'current':''}"><b>03</b> Twin 생성</span></div>
 <div class="build-grid"><div class="stack">
 <section class="card"><div class="card-head"><h2>${icon('upload')} 소비 데이터 연결</h2><span class="tag">UTF-8 CSV</span></div><div class="card-body">
 <input id="csv-files" type="file" accept=".csv,text/csv" multiple hidden>
 <div class="dropzone" id="dropzone" role="button" tabindex="0" aria-label="CSV 파일 선택"><div class="upload-icon">${icon('upload')}</div><strong>소비 CSV를 여기에 놓아주세요</strong><p>한 사용자의 파일 최대 4개 · 합계 8 MB · 10,000건</p><span class="btn">${icon('plus')} 파일 선택</span></div>
 ${p?`<div class="file-list">${p.filenames.map(n=>`<div class="file-item">${icon('file')} ${esc(n)}</div>`).join('')}</div>`:''}
 <div class="section-label">또는, 첨부된 페르소나로 시작하기</div><div class="demo-buttons">${state.config.demos.map(d=>`<button class="demo-btn" data-action="demo" data-id="${d.id}" ${state.busy?'disabled':''}><span>CONSUMER ${d.id}</span><b>${d.name}</b></button>`).join('')}</div>
 <div class="spacer-12"></div><p class="small muted">임의의 은행 CSV가 아닌, 제공된 소비001~004 스키마를 사용합니다.</p>
 <details class="disclosure"><summary>필수 CSV 열 · 형식 확인</summary><p class="schema-info">${state.config.required_csv_columns.map(esc).join(', ')}</p><p class="small muted">source=SEED 또는 LIVE, amount_krw=원 단위 정수. 서로 다른 사용자의 파일은 함께 만들 수 없습니다.</p></details>
 </div></section>
 <section class="card"><div class="card-head"><h2>${icon('wallet')} 기준 상태 설정</h2><span class="tag">OPTIONAL SNAPSHOT</span></div><div class="card-body">
 <div class="fields"><label class="field"><span>Twin 이름</span><input id="twin-name" maxlength="80" value="${esc(b.name)}" placeholder="예: 서준의 금융 Twin"></label><label class="field"><span>시뮬레이션 기준일</span><input id="build-as-of" type="date" value="${esc(b.asOf)}"><small>기본값: 마지막 거래일. 오늘 날짜로 임의 변경하지 않습니다.</small></label></div>
 <div class="spacer-12"></div><div class="segmented" aria-label="현재 상태 입력 방식">${[['history','이력만 사용'],['manual','현재 상태 입력'],['json','JSON 직접 입력']].map(([t,n])=>`<button data-action="snapshot-type" data-type="${t}" class="${b.type===t?'selected':''}">${n}</button>`).join('')}</div>
 ${b.type==='history'?`<div class="note">소비 이력만으로 Twin을 생성합니다. 소비·자금 여력 변화는 계산하지만, 현재 잔액은 추정하지 않습니다. 잔액 정보가 필요한 목표·최적화 모드는 <b>insufficient_data</b>를 반환할 수 있습니다.</div>`:b.type==='manual'?manualSnapshot():`<div class="button-row"><label class="btn" for="snapshot-file">${icon('upload')} 스냅샷 JSON 불러오기</label><input id="snapshot-file" type="file" accept=".json,application/json" hidden><button class="btn ghost" data-action="snapshot-schema">스키마 저장</button></div><textarea id="snapshot-json" class="json-editor snapshot-editor" spellcheck="false" aria-label="현재 상태 snapshot JSON" placeholder="CSV를 분석한 뒤 스냅샷을 입력하세요.">${esc(b.snapshotText)}</textarea><p class="small muted">계좌·카드 ID는 업로드 CSV와 일치해야 합니다. 자산·부채·예정 결제·예산 등 전체 필드를 편집할 수 있습니다.</p>`}
 ${b.isDemo&&b.type!=='history'?'<div class="note warning spaced">데모 잔액·카드 정책은 <b>USER_ASSUMPTION</b>입니다. 소비 CSV에서 확인된 실제 잔액이 아닙니다.</div>':''}
 <div class="spacer-12"></div><button id="build-button" class="btn primary full-width" data-action="build" ${!p||state.busy?'disabled':''}>${icon('plus')} FDT 엔진 생성 ${icon('arrow')}</button>
 </div></section></div>
 <div class="stack build-side"><section class="profile-card"><div class="eyebrow">YOUR FINANCIAL TWIN</div><h2>${p?esc(p.user_id):'과거의 기록에서,<br>다음 금융 상태로.'}</h2><p>${p?'CSV 분석 완료. 기준 상태를 설정하면<br>다섯 가지 모드를 실행할 수 있습니다.':'소비 이력은 관측값으로,<br>입력한 잔액은 명시적인 기준 상태로.'}</p>${profileArt()}
 <dl><div><dt>관측 거래</dt><dd>${p?p.rows.toLocaleString():'—'} <span class="small">건</span></dd></div><div><dt>금융 연결</dt><dd>${p?p.account_ids.length+p.card_ids.length:'—'} <span class="small">계좌·카드</span></dd></div><div><dt>관측 시작일</dt><dd class="small">${p?esc(p.from_date):'CSV 업로드 후 확인'}</dd></div><div><dt>마지막 거래일</dt><dd class="small">${p?esc(p.as_of):'CSV 업로드 후 확인'}</dd></div></dl><div class="source-label">${p?`중복 제외 ${p.duplicates_ignored}건 · 한 사용자 단위 모델`:'기록에 없는 현재 잔액은 0으로 채우지 않습니다.'}</div></section>
 <section class="card expectation"><h3>생성 후 확인할 수 있어요</h3>${[['chart','수치화된 미래','일별 예측, 모델상 확률, 소비 분위수'],['code','정형 JSON 결과','metrics · datasets · visualizations'],['shield','가정과 한계','누락 입력, 추정 근거, 모델 경고']].map(([ic,t,d])=>`<div class="expect-row">${icon(ic)}<div><strong>${t}</strong><p>${d}</p></div></div>`).join('')}</section>
 ${b.result?`<section class="card build-result"><div class="card-head"><h2>생성 결과</h2><button class="btn ghost" data-action="download-twin">${icon('download')} JSON</button></div><pre class="json-view">${esc(pretty(b.result))}</pre><div class="card-body"><a class="btn primary full-width" href="#/forecast">미래 예측 실행하기 ${icon('arrow')}</a></div></section>`:''}
 </div></div>
 <section class="saved-section"><div class="section-head"><h2>저장된 Twin <span class="output-count">${state.twins.length}</span></h2><div class="button-row"><button class="btn ghost" data-action="clear-uploads">임시 업로드 정리</button><button class="btn ghost" data-action="refresh-twins">${icon('refresh')} 새로고침</button></div></div><div class="saved-grid">${state.twins.length?state.twins.map(t=>`<article class="card twin-card ${t.id===state.activeId?'active':''}"><span class="tag ${t.absolute_cash_ready?'success':'warning'}">${t.absolute_cash_ready?'현재 상태 포함':'이력 전용'}</span><h3>${esc(t.name)}</h3><p>${esc(t.user_id)} · ${t.transaction_count}건</p><p>기준일 ${esc(t.as_of)}</p><div class="button-row"><button class="btn ${t.id===state.activeId?'primary':''}" data-action="select-twin" data-id="${t.id}" ${state.busy?'disabled':''}>${t.id===state.activeId?'활성 Twin':'선택'}</button><button class="btn ghost" data-action="inspect-twin" data-id="${t.id}">상태 JSON</button><button class="btn ghost" data-action="delete-twin" data-id="${t.id}" aria-label="${esc(t.name)} 삭제" ${state.busy?'disabled':''}>${icon('trash')}</button></div></article>`).join(''):'<div class="empty-list">아직 생성된 Twin이 없습니다. CSV를 연결해 첫 Twin을 만들어보세요.</div>'}</div></section>`;
}
function initManual(){const p=state.build.profile;if(!p)return null;return {accounts:p.account_ids.map(id=>({account_id:id,balance:''})),cards:p.card_ids.map(id=>({card_id:id,kind:'',account:p.account_ids.length===1?p.account_ids[0]:'',opening:'',delay:2,due:''})),reserve:0};}
function manualSnapshot(){const b=state.build;if(!b.profile)return '<div class="note">CSV를 먼저 업로드하면 계좌·카드 ID를 자동으로 가져옵니다.</div>';b.manual??=initManual();const s=b.manual;return `<div class="note">입력값은 사용자 가정(<b>USER_ASSUMPTION</b>)으로 저장됩니다. 확인한 잔액과 카드 종류를 직접 입력하세요.</div>
 <div class="section-label">계좌 잔액 (기준일 마감)</div>${s.accounts.map((a,i)=>`<div class="manual-account"><span class="mono">${esc(a.account_id)}</span><label class="field"><span>잔액 (원)</span><input type="number" data-manual="accounts.${i}.balance" value="${esc(a.balance)}" min="-1000000000000" max="1000000000000" step="1" placeholder="잔액 직접 입력"></label></div>`).join('')}
 <p class="small muted spaced">계좌 추가·여러 청구서·자산·부채·월 예산은 JSON 직접 입력에서 설정하세요.</p>
 ${s.cards.map((c,i)=>`<div class="repeat-card spaced"><div class="row-head"><b>${esc(c.card_id)}</b><span>카드 정책</span></div><div class="fields"><label class="field"><span>종류</span><select data-manual="cards.${i}.kind"><option value="">선택하세요</option><option value="DEBIT" ${c.kind==='DEBIT'?'selected':''}>체크카드</option><option value="CREDIT" ${c.kind==='CREDIT'?'selected':''}>신용카드</option></select></label><label class="field"><span>출금 계좌</span><select data-manual="cards.${i}.account"><option value="">선택하세요</option>${s.accounts.map(a=>`<option value="${esc(a.account_id)}" ${c.account===a.account_id?'selected':''}>${esc(a.account_id)}</option>`).join('')}</select></label><label class="field"><span>기초 미결제액 (신용카드 · 원)</span><input type="number" data-manual="cards.${i}.opening" value="${esc(c.opening)}" min="0" max="1000000000000" step="1" placeholder="체크카드는 0"></label><label class="field"><span>승인 후 정산 지연 (일)</span><input type="number" data-manual="cards.${i}.delay" value="${esc(c.delay)}" min="0" max="31" step="1"><small>테스트 모델의 정산 가정. 실제 청구 주기가 아닙니다.</small></label><label class="field full"><span>기초 미결제액 납부일 (미결제액 &gt; 0일 때)</span><input type="date" data-manual="cards.${i}.due" value="${esc(c.due)}"><small>입력 미결제액 전액을 이 날짜의 known_bills 1건으로 생성합니다.</small></label></div></div>`).join('')}
 <label class="field spaced"><span>보호할 예비자금 (원)</span><input type="number" data-manual="reserve" value="${esc(s.reserve)}" min="0" max="1000000000000" step="1"></label><button class="btn ghost spaced" data-action="manual-to-json">${icon('code')} 이 입력을 JSON으로 전환</button>`;}
function composeSnapshot(){const b=state.build;if(b.type==='history')return null;if(b.type==='json'){const data=JSON.parse(b.snapshotText);if(!data||typeof data!=='object'||Array.isArray(data))throw new Error('스냅샷은 JSON 객체여야 합니다.');return data;}
 const m=b.manual;if(!m)throw new Error('CSV를 먼저 업로드하세요.');const finite=(s,label)=>{if(s===''||s===null||!Number.isFinite(Number(s))||!Number.isInteger(Number(s)))throw new Error(label+'을 정수로 입력하세요.');return Number(s);};
 const s={as_of:b.asOf,source:'USER_ASSUMPTION',accounts:m.accounts.map(a=>({account_id:a.account_id,balance_krw:finite(a.balance,a.account_id+' 잔액')})),cards:[],known_bills:[],reserve_krw:finite(m.reserve,'예비자금'),coverage:{all_assets_reported:false,all_liabilities_reported:false}};
 for(const [i,c] of m.cards.entries()){if(!c.kind||!c.account)throw new Error(c.card_id+'의 카드 종류와 출금 계좌를 선택하세요.');const row={card_id:c.card_id,kind:c.kind,settlement_account_id:c.account};if(c.kind==='DEBIT'&&c.opening!==''&&Number(c.opening)!==0)throw new Error('체크카드의 기초 미결제액은 0이어야 합니다.');if(c.kind==='CREDIT'){row.opening_payable_krw=finite(c.opening,'미결제액');row.payment_delay_days=finite(c.delay,'정산 지연일');if(row.opening_payable_krw>0){if(!c.due)throw new Error('기초 미결제액의 납부일을 입력하세요.');s.known_bills.push({bill_id:'manual-bill-'+i,card_id:c.card_id,due_date:c.due,amount_krw:row.opening_payable_krw});}}s.cards.push(row);}return s;
}
function scenarioFields(req,prefix='scenario'){
 const scenario=getAt(req,prefix)||{};const accounts=[...new Set((state.active?.summary?.relationships?.nodes||[]).filter(n=>n.type==='account').map(n=>n.id))];
 const reductions=`<div class="envelope-grid">${state.config.envelopes.map(env=>`<label class="envelope-field"><span>${esc(env)}</span><span><input type="number" aria-label="${esc(env)} 감축률" data-path="${prefix}.expense_reductions.${env}" data-scale="100" value="${Math.round((scenario.expense_reductions?.[env]||0)*1e10)/1e8}" min="0" max="100" step="1"><span class="suffix">%</span></span></label>`).join('')}</div>`;
 const events=(scenario.cash_events||[]).map((e,i)=>`<div class="repeat-card spaced"><div class="row-head"><span>이벤트 ${i+1}</span><button type="button" class="btn ghost" data-action="remove-event" data-index="${i}">${icon('trash')}</button></div><div class="fields"><label class="field"><span>날짜</span><input data-path="${prefix}.cash_events.${i}.date" type="date" value="${esc(e.date)}"></label><label class="field"><span>방향</span><select data-path="${prefix}.cash_events.${i}.direction"><option value="EXPENSE" ${e.direction==='EXPENSE'?'selected':''}>지출</option><option value="INCOME" ${e.direction==='INCOME'?'selected':''}>수입</option></select></label>${numericField('금액',`${prefix}.cash_events.${i}.amount_krw`,e.amount_krw,{unit:'원'})}<label class="field"><span>계좌 ID</span><input data-path="${prefix}.cash_events.${i}.account_id" value="${esc(e.account_id)}" list="account-options"></label><label class="field"><span>고정지출 그룹 (지출만)</span><select data-path="${prefix}.cash_events.${i}.fixed_group" ${e.direction==='EXPENSE'?'':'disabled'}><option value="">일반 현금 이벤트</option>${(state.config.fixed_groups||[]).map(g=>`<option value="${esc(g)}" ${e.fixed_group===g?'selected':''}>${esc(g)}</option>`).join('')}</select></label></div></div>`).join('');
 return `<div class="fields">${textField('시나리오 이름',prefix+'.name',scenario.name)}${numericField('투자 평가액 충격',prefix+'.asset_shock_fraction',scenario.asset_shock_fraction||0,{unit:'%',min:-100,max:500,scale:100,hint:'현금 유입이 아닌, 입력된 투자 평가액의 정적 변화'})}</div><div class="row-label">소비 감축률 · 고정/반복 지출은 보호</div>${reductions}<div class="fields spaced">${numericField('소득 수준',prefix+'.income_multiplier',scenario.income_multiplier??1,{unit:'%',max:500,scale:100,hint:'100% = 기존 소득, 80% = 20% 감소'})}${numericField('소비 물가 수준',prefix+'.expense_multiplier',scenario.expense_multiplier??1,{unit:'%',max:500,scale:100,hint:'100% = 기존 수준, 110% = 10% 상승'})}${numericField('고정지출 수준',prefix+'.fixed_multiplier',scenario.fixed_multiplier??1,{unit:'%',max:500,scale:100,hint:'100% = 기존 수준, 110% = 10% 상승'})}</div>${fixedOverrideFields(scenario,prefix)}
 <details class="disclosure"><summary>일회성 현금 이벤트 · ${(scenario.cash_events||[]).length}건</summary><p class="small muted">기준일 이후, 예측 기간 안의 날짜를 사용하세요. 실제 이체는 실행하지 않습니다.</p>${events}<datalist id="account-options">${accounts.map(a=>`<option value="${esc(a)}"></option>`).join('')}</datalist><button type="button" class="btn spaced" data-action="add-event">${icon('plus')} 현금 이벤트 추가</button></details>
 <details class="disclosure"><summary>반복 일정 취소 · ${(scenario.cancel_rule_ids||[]).length}건 선택</summary><p class="small muted">실제 계약 해지가 아니라 시뮬레이션에서 해당 일정을 제외합니다.</p><div class="cancel-rules">${(state.active?.summary?.recurring_rules||[]).map(r=>`<label class="rule-row"><input type="checkbox" data-rule="${esc(r.rule_id)}" ${(scenario.cancel_rule_ids||[]).includes(r.rule_id)?'checked':''}><span><strong>${esc(r.rule_id)}</strong>${esc(r.merchant_id||'')} · ${Number(r.expected_amount_krw||0).toLocaleString()}원 · ${esc(r.next_date||'')}</span></label>`).join('')||'<p class="small muted">활성 Twin의 반복 일정이 없습니다.</p>'}</div></details>`;
}
function goalFields(req){const g=req.goal||{};return `<div class="fields">${numericField('목표 금액','goal.target_krw',g.target_krw??3000000,{unit:'원',hint:'예측 기간 마지막 날의 가용 현금 목표'})}${numericField('보호할 예비자금','goal.reserve_krw',g.reserve_krw,{unit:'원',required:false,hint:'비우면 스냅샷의 예비자금, 없으면 0원'})}${numericField('필요 성공 확률','goal.success_probability',g.success_probability??.8,{unit:'%',max:100,scale:100,hint:'목표 달성과 기간 중 계좌 부족 없음의 동시 조건'})}<div class="field"><span>목표일</span><div class="note" id="deadline">${deadlineLabel(req.horizon_days)}</div></div></div>`;}
function deadlineLabel(horizon){if(!state.active)return 'Twin을 선택하세요';const d=new Date(state.active.meta.as_of+'T00:00:00Z');d.setUTCDate(d.getUTCDate()+Number(horizon||90));return d.toISOString().slice(0,10);}
function stressFields(req){return `<p class="small muted">최대 5개. 비율은 기준 시나리오에 대한 변경 가정입니다.</p><div class="spacer-12"></div>${(req.stress_scenarios||[]).map((s,i)=>`<div class="repeat-card"><div class="row-head"><b>충격 ${String(i+1).padStart(2,'0')}</b><button type="button" class="btn ghost" data-action="remove-stress" data-index="${i}">${icon('trash')}</button></div>${textField('이름',`stress_scenarios.${i}.name`,s.name)}<div class="fields spaced">${numericField('소득 수준',`stress_scenarios.${i}.income_multiplier`,s.income_multiplier,{unit:'%',max:500,scale:100,required:false,hint:'비우면 기준 시나리오 유지'})}${numericField('소비 물가 수준',`stress_scenarios.${i}.expense_multiplier`,s.expense_multiplier,{unit:'%',max:500,scale:100,required:false,hint:'비우면 기준 시나리오 유지'})}${numericField('고정지출 수준',`stress_scenarios.${i}.fixed_multiplier`,s.fixed_multiplier,{unit:'%',max:500,scale:100,required:false,hint:'비우면 기준 시나리오 유지'})}${numericField('투자 평가액 충격',`stress_scenarios.${i}.asset_shock_fraction`,s.asset_shock_fraction,{unit:'%',min:-100,max:500,scale:100,required:false,hint:'비우면 기준 시나리오 유지'})}</div></div>`).join('')}<button type="button" class="btn" data-action="add-stress" ${(req.stress_scenarios||[]).length>=5?'disabled':''}>${icon('plus')} 충격 시나리오 추가</button><p class="small muted spaced">빈 배열은 외부 충격 비교를 생략합니다. 상세 소비 감축·현금 이벤트는 JSON에서 편집하세요.</p>`;}
function optimizationFields(req){const o=req.optimization||{},envs=o.envelopes||[],grid=o.reduction_grid||[];return `<div class="row-label">감축 대상 봉투 (최대 4개)</div><div class="chip-list">${state.config.envelopes.map(e=>`<label class="check-chip"><input type="checkbox" data-opt-envelope="${esc(e)}" ${envs.includes(e)?'checked':''}>${esc(e)}</label>`).join('')}</div><div class="fields spaced"><label class="field"><span>감축률 후보 (%)</span><input id="reduction-grid" value="${esc(state.gridDraft??grid.map(v=>Math.round(v*10000)/100).join(', '))}" placeholder="0, 10, 20"><small>쉼표로 구분. 서로 다른 값 1~6개, 조합 최대 128개.</small></label>${numericField('허용 계좌 부족 확률','optimization.max_shortfall_probability',o.max_shortfall_probability??.1,{unit:'%',max:100,scale:100})}</div><div class="note spaced" id="candidate-count">예상 후보 <b>${grid.length**envs.length}개</b> · 유한 후보 전체 탐색</div><details class="disclosure"><summary>봉투별 최소 월 변동소비 금액</summary><div class="fields spaced">${state.config.envelopes.map(e=>numericField(e,`optimization.minimum_remaining_monthly_krw.${e}`,o.minimum_remaining_monthly_krw?.[e],{unit:'원',required:false,hint:'비우면 제한 없음'})).join('')}</div></details>`;}
function modeForm(req){const mode=state.route;let body=section('01','시뮬레이션 설정',`<div class="fields three">${numericField('예측 기간','horizon_days',req.horizon_days,{unit:'일',min:1,max:365})}${numericField('시뮬레이션 경로','paths',req.paths,{min:20,max:2000,hint:'20~2,000개'})}${numericField('난수 시드','seed',req.seed,{max:4294967295,hint:'같은 입력·시드로 재현'})}</div>`);
 if(mode==='what_if')body+=section('02','변경 시나리오',scenarioFields(req));
 if(mode==='goal'||mode==='optimize')body+=section('02','목표와 안전 조건',goalFields(req));
 if(mode==='risk')body+=section('02','외부 충격 시나리오',stressFields(req));
 if(mode==='optimize')body+=section('03','탐색할 행동 후보',optimizationFields(req));
 if(mode!=='what_if')body+=`<details class="disclosure"><summary>기준 시나리오 추가 설정</summary><div class="spacer-12"></div>${scenarioFields(req)}</details>`;
 return body;
}
function modePage(){const mode=state.route,req=state.requests[mode],active=state.active,raw=state.editors[mode]==='json';return `
 ${active?`<div class="twin-meta-bar"><span>${icon('wallet')} <strong>${esc(active.meta.name)}</strong> · ${esc(active.meta.user_id)}</span><span class="meta-right"><span>기준 ${esc(active.meta.as_of)}</span><span>${active.meta.transaction_count}건 관측</span><span class="tag ${active.meta.absolute_cash_ready?'success':'warning'}">${active.meta.absolute_cash_ready?'현재 상태 포함':'이력 전용'}</span></span></div>`:'<div class="note warning spaced">활성 Twin이 없습니다. <a href="#/build"><b>CSV 업로드 페이지</b></a>에서 먼저 생성하세요.</div><div class="spacer-12"></div>'}
 ${active&&!active.meta.absolute_cash_ready?'<div class="note warning inline-error">현재 잔액·카드 정산 정보가 없습니다. 절대 잔액은 null이며, 목표·최적화 판정은 insufficient_data일 수 있습니다.</div>':''}
 <div class="mode-grid"><section class="card mode-input"><div class="card-head"><h2>${icon('sliders')} 입력 파라미터</h2><span class="tag">${mode}</span></div>
 <form id="mode-form"><div class="card-body"><div class="segmented"><button type="button" data-action="editor" data-editor="form" class="${!raw?'selected':''}">폼으로 입력</button><button type="button" data-action="editor" data-editor="json" class="${raw?'selected':''}">JSON 직접 편집</button></div>
 <div class="request-tools"><button type="button" class="btn ghost" data-action="reset-request">${icon('refresh')} 기본값</button><div class="button-row"><label for="request-file" class="btn">${icon('upload')} 불러오기</label><input id="request-file" type="file" accept=".json,application/json" hidden><button type="button" class="btn" data-action="download-request">${icon('download')} 요청 저장</button></div></div>
 ${raw?`<div class="form-mode-json"><div class="note">엔진의 모든 입력 필드를 그대로 편집합니다. 이 페이지에서는 <b>mode: ${mode}</b>를 유지하세요. 비율의 JSON 값은 20% = 0.2입니다.</div><textarea id="request-json" class="json-editor spaced" spellcheck="false" aria-label="모드 요청 JSON">${esc(state.raw[mode]??pretty(req))}</textarea><button type="button" class="btn ghost" data-action="format-request">${icon('code')} JSON 정렬</button></div>`:modeForm(req)}
 <details class="disclosure"><summary>실행할 요청 JSON 확인</summary><pre id="request-preview">${esc(pretty(req))}</pre></details></div>
 <div class="run-footer"><button id="run-button" type="submit" class="btn primary full-width" ${!active||state.busy?'disabled':''}>${icon('play')} ${MODES[mode].name} 실행 ${icon('arrow')}</button><p class="hint">실제 금융 거래·자연어 AI 호출은 실행하지 않습니다.</p></div></form></section>
 <section class="card mode-output"><div class="card-head output-head"><h2><span class="dot"></span> 엔진 Output</h2><span id="output-badge" class="tag">READY</span></div><div id="output-status"></div><div class="output-tabs" role="tablist" aria-label="결과 보기">${[['json','결과 JSON'],['metrics','핵심 수치'],['charts','시각화'],['warnings','가정·경고'],['request','실행 입력']].map(([tab,label])=>`<button class="output-tab ${((state.tabs[mode]||'json')===tab)?'selected':''}" data-action="output-tab" data-tab="${tab}" role="tab" aria-selected="${((state.tabs[mode]||'json')===tab)}">${label}</button>`).join('')}</div><div id="stale-note" class="stale-note" hidden>입력이 변경되었습니다. 아래 결과는 마지막 실행 입력 기준입니다.</div><div id="output-content" class="output-content"></div></section></div>`;
}
const METRIC_NAMES={terminal_cash_p50_krw:'마지막 날 현금 · P50',expected_expense_krw:'평균 예상 총소비',total_expense_p50_krw:'총소비 · P50',p_any_account_shortfall:'기간 중 계좌 부족 확률',p_total_cash_shortfall:'기간 중 총현금 부족 확률',terminal_resource_change_p50_krw:'자금 여력 변화 · P50',p_goal_reached:'만기 목표 달성 확률',p_goal_and_no_shortfall:'목표 달성 + 계좌 부족 없음',goal_gap_p50_krw:'목표 부족액 · P50',goal_target_krw:'목표 금액',candidate_count:'평가한 후보 수',feasible_candidate_count:'조건 충족 후보 수',selected_expected_saving_krw:'선택안 예상 소비 감축액',paired_expense_saving_p50_krw:'변경안 절감액 · P50',paired_terminal_cash_delta_p50_krw:'기준 대비 현금 차이 · P50',p_liquid_below_reserve:'예비자금 미만 확률'};
function metricValue(m){if(m.value===null||m.value===undefined)return '알 수 없음';if(m.unit==='probability'||m.unit==='ratio')return (m.value*100).toLocaleString('ko-KR',{maximumFractionDigits:1})+'%';return Number(m.value).toLocaleString('ko-KR',{maximumFractionDigits:2})+(m.unit==='KRW'?'원':m.unit==='count'?'개':'');}
function resultToolbar(filename,label){return `<div class="json-toolbar"><span>${esc(filename)}</span><div class="button-row"><button class="btn" data-action="copy-output" data-which="${label}">${icon('copy')} 복사</button><button class="btn" data-action="download-output" data-which="${label}">${icon('download')} 저장</button></div></div>`;}
function renderOutput(){if(state.route==='build')return;const mode=state.route,o=state.outputs[mode],el=document.querySelector('#output-content');if(!el)return;
 document.querySelectorAll('.output-tab').forEach(e=>{e.classList.toggle('selected',e.dataset.tab===(state.tabs[mode]||'json'));e.setAttribute('aria-selected',String(e.classList.contains('selected')));});
 const badge=document.querySelector('#output-badge'),status=document.querySelector('#output-status');const isRunning=state.busy?.mode===mode;
 badge.textContent=isRunning?'RUNNING':o?.error?'ERROR':o?.cancelled?'CANCELLED':o?.result?o.result.status.toUpperCase():'READY';badge.className='tag'+(o?.error&&!isRunning?' error':o?.result&&!isRunning?(o.result.status==='ok'?' success':' warning'):'');
 status.innerHTML=isRunning?`<div class="run-status"><span class="status-text"><span class="spinner"></span> 엔진 계산 중 · <span id="mode-elapsed">0.0</span>초</span><button class="btn danger" data-action="cancel-job">취소</button></div>`:o?.error?`<div class="run-status failed" role="alert">${esc(o.error)}${o.result?' · 아래는 이전 완료 실행 결과입니다.':''}</div>`:o?.cancelled?'<div class="run-status cancelled">계산을 취소했습니다. 아래 결과가 있다면 이전 완료 실행의 결과입니다.</div>':o?.result?`<div class="run-status"><span>${o.result.status==='ok'?'계산 완료':'부분 결과 · 누락 입력 확인'} · ${Number(o.elapsed||0).toFixed(2)}초</span><small>${esc(o.twinName)} · ${esc(o.result.as_of)}</small></div>`:'';
 if(!o?.result){el.innerHTML=`<div class="output-empty">${isRunning?'<div class="spinner large"></div>':`<div class="empty-symbol">${icon('code')}</div>`}<h3>${isRunning?'가능한 금융 경로를 계산 중입니다.':'입력이 준비되면, 결과가 여기에.'}</h3><p>${isRunning?'모델 경로와 제약 조건을 평가하고 있습니다. 실제 금융망에는 접근하지 않습니다.':'왼쪽에서 파라미터를 설정하고 실행하세요. 엔진이 반환한 JSON 원문을 확인할 수 있습니다.'}</p><div class="pipeline"><span>INPUT</span>→<span>FDT ENGINE</span>→<span>JSON</span></div></div>`;markStale();return;}
 const result=o.result,tab=state.tabs[mode]||'json';
 if(tab==='json')el.innerHTML=resultToolbar(mode+'_result.json','result')+`<pre class="json-view" tabindex="0" aria-label="엔진 결과 JSON">${esc(pretty(result))}</pre>`;
 if(tab==='request')el.innerHTML=resultToolbar(mode+'_request.json','request')+`<pre class="json-view" tabindex="0">${esc(pretty(o.request))}</pre>`;
 if(tab==='metrics'){
 let keys=mode==='goal'?['p_goal_reached','p_goal_and_no_shortfall','goal_gap_p50_krw','goal_target_krw']:mode==='what_if'?['paired_expense_saving_p50_krw','paired_terminal_cash_delta_p50_krw','p_any_account_shortfall','branch_p_any_account_shortfall']:mode==='optimize'?['candidate_count','feasible_candidate_count','selected_expected_saving_krw','p_any_account_shortfall']:mode==='risk'?['p_any_account_shortfall','p_total_cash_shortfall','p_liquid_below_reserve','expected_expense_krw']:['terminal_cash_p50_krw','expected_expense_krw','p_any_account_shortfall','terminal_resource_change_p50_krw'];
 el.innerHTML=`<div class="output-pad"><div class="metrics-grid">${keys.filter(k=>result.metrics[k]).map(k=>{const m=result.metrics[k];return `<div class="metric-tile"><label>${esc(METRIC_NAMES[k]||k)}</label><strong>${esc(metricValue(m))}</strong><small>${esc(k)}</small><small>${esc(m.basis)}</small></div>`;}).join('')}</div>${result.decision?`<details class="disclosure" open><summary>판정 · Decision</summary><pre>${esc(pretty(result.decision))}</pre></details>`:''}<div class="divider"></div><h3>전체 Metrics</h3><div class="spacer-12"></div>${tableMarkup(Object.entries(result.metrics).map(([key,m])=>({metric:key,value:m.value,unit:m.unit,basis:m.basis})),200)}</div>`;
 }
 if(tab==='charts')el.innerHTML=`<div class="output-pad"><div class="note warning">그래프는 엔진의 visualizations 명세와 datasets로 그립니다. P10~P90은 모델 경로의 분위수이며 실세계 결과를 보장하는 구간이 아닙니다.</div><div class="spacer-12"></div>${result.visualizations.map(s=>`<section class="chart-card"><h3>${esc(s.title)}</h3>${chartMarkup(s,result.datasets[s.dataset]||[])}<small>${esc(s.note)}</small><details class="disclosure"><summary>시각화 명세</summary><pre>${esc(pretty(s))}</pre></details></section>`).join('')}</div>`;
 if(tab==='warnings')el.innerHTML=`<div class="output-pad">${result.required_inputs?.length?`<div class="note warning"><b>추가로 필요한 입력</b><br>${result.required_inputs.map(esc).join('<br>')}</div><div class="spacer-12"></div>`:''}<h3>가정 · Assumptions</h3>${result.assumptions.map(a=>`<div class="warning-item"><b>${esc(a.code)} · ${esc(a.source)}</b>${esc(a.detail||'요청에서 전달된 조건입니다.')}<details class="disclosure"><summary>원문</summary><pre>${esc(pretty(a))}</pre></details></div>`).join('')}<div class="divider"></div><h3>경고 · Warnings</h3>${result.warnings.map(w=>`<div class="warning-item"><b>${esc(w.code)}</b>${esc(w.message||w.detail||pretty(w))}</div>`).join('')}<div class="divider"></div><h3>모델 한계</h3>${result.limitations.map(s=>`<div class="warning-item">${esc(s)}</div>`).join('')}</div>`;
 markStale();
}
function readCurrentRequest(){let req=state.editors[state.route]==='json'?JSON.parse(state.raw[state.route]):clone(state.requests[state.route]);if(!req||Array.isArray(req)||typeof req!=='object')throw new Error('요청은 JSON 객체여야 합니다.');if(req.mode!==state.route)throw new Error('mode 값은 현재 페이지('+state.route+')와 같아야 합니다.');return req;}
function markStale(){const el=document.querySelector('#stale-note');if(!el)return;const o=state.outputs[state.route];if(!o?.result){el.hidden=true;return;}try{el.hidden=pretty(readCurrentRequest())===pretty(o.request)&&state.activeId===o.recordId;}catch{el.hidden=false;}}
function refreshPreviews(){const pre=document.querySelector('#request-preview');if(pre){try{pre.textContent=pretty(readCurrentRequest());}catch{pre.textContent='올바른 JSON을 입력하세요.';}}const d=document.querySelector('#deadline');if(d)d.textContent=deadlineLabel(state.requests[state.route]?.horizon_days);const c=document.querySelector('#candidate-count');if(c){const o=state.requests[state.route]?.optimization||{};const n=(o.reduction_grid||[]).length**(o.envelopes||[]).length;c.textContent=`예상 후보 ${n}개 · 최대 128개 · 유한 후보 전체 탐색`;}markStale();}
async function refreshTwins(){const data=await api('/api/twins');state.twins=data.twins;}
async function selectTwin(id){if(!id){state.activeId='';state.active=null;localStorage.removeItem('keyfin_active_twin');render();return;}const value=await api('/api/twins/'+id);state.active=value;state.activeId=id;localStorage.setItem('keyfin_active_twin',id);render();}
async function uploadFiles(files,{demo=false}={}){
 if(state.busy)throw new Error('진행 중인 작업을 먼저 완료하거나 취소하세요.');
 if(!files.length)return;if(files.length>4)throw new Error('최대 4개 파일을 선택하세요.');if([...files].reduce((n,f)=>n+f.size,0)>8*1024*1024)throw new Error('CSV 합계는 8 MB 이하여야 합니다.');
 state.busy={label:'CSV 분석',id:null};state.error=null;render();
 try{const form=new FormData();for(const file of files)form.append('files',file);const result=await api('/api/uploads',{method:'POST',body:form});const p=result.profile;state.build={upload:result.upload_id,profile:p,name:p.user_id+' 금융 Twin',asOf:p.as_of,type:'history',snapshotText:'',manual:null,result:null,isDemo:demo};
 const template={as_of:p.as_of,source:'USER_ASSUMPTION',accounts:p.account_ids.map(id=>({account_id:id,balance_krw:null})),cards:p.card_ids.map(id=>({card_id:id,kind:'CREDIT',settlement_account_id:p.account_ids[0]||'',opening_payable_krw:null,payment_delay_days:2})),known_bills:[],reserve_krw:0,coverage:{all_assets_reported:false,all_liabilities_reported:false}};
 state.build.snapshotText=pretty(template);toast(`${p.rows}건 CSV 분석을 완료했습니다.`);
 }finally{state.busy=null;render();}
}
async function loadDemo(id){const d=state.config.demos.find(x=>x.id===id);const response=await fetch(`/api/demo/${id}/csv`);if(!response.ok)throw new Error('데모 CSV를 읽지 못했습니다.');const file=new File([await response.blob()],`consumer_${id}.csv`,{type:'text/csv'});await uploadFiles([file],{demo:true});const snapshot=await api(`/api/demo/${id}/snapshot`);state.build.name=d.name+' 데모 Twin';state.build.type='json';state.build.snapshotText=pretty(snapshot);render();}
async function waitJob(id){for(;;){const job=await api('/api/jobs/'+id);for(const key of ['#global-elapsed','#mode-elapsed']){const e=document.querySelector(key);if(e)e.textContent=job.elapsed_seconds.toFixed(1);}if(job.status==='succeeded')return {job,result:await api(job.result_url)};if(job.status==='failed')throw Object.assign(new Error(job.error.message),job.error);if(job.status==='cancelled')return {job,result:null};await new Promise(r=>setTimeout(r,300));}}
async function buildTwin(){if(state.busy)throw new Error('진행 중인 작업이 있습니다.');if(!state.build.upload)throw new Error('CSV를 먼저 업로드하세요.');if(!state.build.name.trim())throw new Error('Twin 이름을 입력하세요.');
 const payload={upload_id:state.build.upload,name:state.build.name,as_of:state.build.asOf,snapshot:composeSnapshot()};state.error=null;state.busy={label:'금융 Twin 생성',id:null};render();
 try{const job=await api('/api/twins',{method:'POST',body:payload});state.busy.id=job.id;render();const done=await waitJob(job.id);if(done.result){state.build.result=done.result;await refreshTwins();const id=done.job.twin.id;state.active=await api('/api/twins/'+id);state.activeId=id;localStorage.setItem('keyfin_active_twin',id);toast('Twin 생성 완료. 다섯 가지 모드를 사용할 수 있습니다.');}else toast('Twin 생성을 취소했습니다.');
 }finally{state.busy=null;render();}
}
function parseGrid(text){const parts=text.split(',').map(s=>s.trim());if(!parts.length||parts.some(s=>s===''||!Number.isFinite(Number(s))||Number(s)<0||Number(s)>100))throw new Error('감축률 후보를 0~100 사이의 숫자로 입력하세요. 예: 0, 10, 20');return parts.map(s=>Number(s)/100);}
async function runMode(){if(state.busy)throw new Error('진행 중인 작업이 있습니다.');if(!state.activeId)throw new Error('활성 Twin을 선택하세요.');const mode=state.route;
 if(mode==='optimize'&&state.editors[mode]!=='json'&&state.gridDraft!==undefined)state.requests[mode].optimization.reduction_grid=parseGrid(state.gridDraft);
 const request=readCurrentRequest(),id=state.activeId,twinName=state.active.meta.name;const previous=state.outputs[mode];state.outputs[mode]=previous?{...previous,error:null,cancelled:false}:{};state.error=null;state.busy={mode,label:MODES[mode].name,id:null};render();
 try{const job=await api(`/api/twins/${id}/runs`,{method:'POST',body:request});state.busy.id=job.id;render();const done=await waitJob(job.id);if(done.result){state.outputs[mode]={result:done.result,request:clone(request),recordId:id,twinName,elapsed:done.job.elapsed_seconds};toast(done.result.status==='ok'?'계산을 완료했습니다.':'결과를 생성했습니다. 누락 입력·경고를 확인하세요.');}else {state.outputs[mode]={...state.outputs[mode],cancelled:true};toast('계산을 취소했습니다.');}
 }catch(e){state.outputs[mode]={...state.outputs[mode],error:errorMessage(e)};throw e;}finally{state.busy=null;render();}
}
function inputChanged(el){const mode=state.route;
 if(el.matches('#twin-name'))state.build.name=el.value;
 if(el.matches('#build-as-of'))state.build.asOf=el.value;
 if(el.matches('#snapshot-json'))state.build.snapshotText=el.value;
 if(el.dataset.manual){state.build.manual??=initManual();setAt(state.build.manual,el.dataset.manual,el.value);}
 if(el.matches('#request-json')){state.raw[mode]=el.value;refreshPreviews();}
 if(el.dataset.path){let value=el.type==='number'?(el.value===''?undefined:Number(el.value)/(Number(el.dataset.scale)||1)):el.value;if(value==='')value=undefined;setAt(state.requests[mode],el.dataset.path,value);refreshPreviews();}
 if(el.matches('#reduction-grid')){state.gridDraft=el.value;try{state.requests[mode].optimization.reduction_grid=parseGrid(el.value);el.setCustomValidity('');}catch(e){el.setCustomValidity(e.message);}refreshPreviews();}
 if(el.dataset.optEnvelope){const o=state.requests[mode].optimization;o.envelopes??=[];o.envelopes=el.checked?[...new Set([...o.envelopes,el.dataset.optEnvelope])]:o.envelopes.filter(e=>e!==el.dataset.optEnvelope);refreshPreviews();}
 if(el.dataset.rule){const r=state.requests[mode];r.scenario??={};r.scenario.cancel_rule_ids??=[];r.scenario.cancel_rule_ids=el.checked?[...new Set([...r.scenario.cancel_rule_ids,el.dataset.rule])]:r.scenario.cancel_rule_ids.filter(id=>id!==el.dataset.rule);refreshPreviews();}
}
main.addEventListener('input',e=>inputChanged(e.target));
main.addEventListener('change',async e=>{const el=e.target;try{
 if(el.id==='csv-files'){await uploadFiles([...el.files]);}
 if(el.id==='snapshot-file'){const f=el.files[0];if(!f)return;if(f.size>1024*1024)throw new Error('JSON은 1 MB 이하로 선택하세요.');const value=JSON.parse((await f.text()).replace(/^\uFEFF/,''));state.build.snapshotText=pretty(value);state.build.type='json';state.build.isDemo=false;render();toast('스냅샷 초안을 불러왔습니다. 계좌 ID와 기준일을 확인하세요.');}
 if(el.id==='request-file'){const f=el.files[0];if(!f)return;if(f.size>1024*1024)throw new Error('JSON은 1 MB 이하로 선택하세요.');const value=JSON.parse((await f.text()).replace(/^\uFEFF/,''));if(value.mode!==state.route)throw new Error('현재 페이지의 mode('+state.route+')와 일치하지 않습니다.');state.raw[state.route]=pretty(value);state.editors[state.route]='json';render();toast('요청 JSON을 편집기에 불러왔습니다.');}
 }catch(e){showError(e);}});
main.addEventListener('submit',async e=>{if(e.target.id!=='mode-form')return;e.preventDefault();try{await runMode();}catch(err){showError(err);}});
function showError(e){state.error=errorMessage(e);render();toast(state.error,true);}
main.addEventListener('click',async e=>{
 if(e.target.closest('#dropzone')){if(!state.busy)document.querySelector('#csv-files')?.click();return;}
 const button=e.target.closest('[data-action]');if(!button)return;const a=button.dataset.action,mode=state.route,req=state.requests[mode];
 try{
 if(a==='dismiss-error'){state.error=null;render();}
 if(a==='demo')await loadDemo(button.dataset.id);
 if(a==='snapshot-type'){state.build.type=button.dataset.type;render();}
 if(a==='manual-to-json'){state.build.snapshotText=pretty(composeSnapshot());state.build.type='json';render();}
 if(a==='snapshot-schema')download(state.config.snapshot_schema,'snapshot.schema.json');
 if(a==='build')await buildTwin();
 if(a==='cancel-job'&&state.busy?.id){await api('/api/jobs/'+state.busy.id+'/cancel',{method:'POST'});toast('작업 취소를 요청했습니다.');}
 if(a==='refresh-twins'){await refreshTwins();render();}
 if(a==='select-twin')await selectTwin(button.dataset.id);
 if(a==='delete-twin'){const id=button.dataset.id,t=state.twins.find(t=>t.id===id);if(!confirm(`“${t.name}”의 로컬 Twin과 원장 데이터를 삭제할까요? 되돌릴 수 없습니다.`))return;await api('/api/twins/'+id,{method:'DELETE'});if(id===state.activeId){state.activeId='';state.active=null;localStorage.removeItem('keyfin_active_twin');}await refreshTwins();render();toast('로컬 Twin을 삭제했습니다.');}
 if(a==='inspect-twin'){const value=await api('/api/twins/'+button.dataset.id);download(value.summary,'twin_state.json');}
 if(a==='download-twin')download(state.build.result,'twin_created.json');
 if(a==='clear-uploads'){await api('/api/uploads',{method:'DELETE'});state.build.upload=null;state.build.profile=null;state.build.manual=null;render();toast('임시 CSV 파일을 정리했습니다. 저장된 Twin은 유지됩니다.');}
 if(a==='output-tab'){state.tabs[mode]=button.dataset.tab;renderOutput();}
 if(a==='download-output'||a==='copy-output'){const o=state.outputs[mode],which=button.dataset.which;const value=which==='request'?o.request:o.result;if(a==='download-output')download(value,mode+'_'+which+'.json');else await copyText(pretty(value));}
 if(a==='download-request')download(readCurrentRequest(),mode+'_request.json');
 if(a==='reset-request'){if(!confirm('현재 입력을 이 모드의 기본값으로 초기화할까요?'))return;state.requests[mode]=clone(state.config.templates[mode]);state.raw[mode]=pretty(state.requests[mode]);if(mode==='optimize')state.gridDraft=undefined;render();}
 if(a==='editor'){const target=button.dataset.editor;if(target==='json'){if(mode==='optimize'&&state.gridDraft!==undefined)req.optimization.reduction_grid=parseGrid(state.gridDraft);if(state.editors[mode]!=='json')state.raw[mode]=pretty(req);}else if(state.editors[mode]==='json'){const parsed=readCurrentRequest();await api('/api/validate/request',{method:'POST',body:parsed});state.requests[mode]={horizon_days:90,paths:400,seed:42,...parsed};if(mode==='risk')state.requests[mode].stress_scenarios??=clone(state.config.templates.risk.stress_scenarios);if(mode==='optimize'){state.requests[mode].optimization={...clone(state.config.templates.optimize.optimization),...(state.requests[mode].optimization||{})};state.requests[mode].goal??={target_krw:0};state.gridDraft=undefined;}}state.editors[mode]=target;render();}
 if(a==='format-request'){state.raw[mode]=pretty(readCurrentRequest());render();}
 if(a==='add-event'){req.scenario??={};req.scenario.cash_events??=[];if(req.scenario.cash_events.length>=100)throw new Error('현금 이벤트는 최대 100개입니다.');const ids=(state.active?.summary?.relationships?.nodes||[]).filter(n=>n.type==='account').map(n=>n.id);req.scenario.cash_events.push({date:deadlineLabel(1),account_id:ids[0]||'',amount_krw:100000,direction:'EXPENSE'});render();document.querySelector('[data-action="add-event"]')?.closest('details')?.setAttribute('open','');}
 if(a==='remove-event'){req.scenario.cash_events.splice(Number(button.dataset.index),1);render();document.querySelector('[data-action="add-event"]')?.closest('details')?.setAttribute('open','');}
 if(a==='add-stress'){req.stress_scenarios??=[];if(req.stress_scenarios.length<5)req.stress_scenarios.push({name:'새 충격 가정',income_multiplier:1,expense_multiplier:1,asset_shock_fraction:0});render();}
 if(a==='remove-stress'){req.stress_scenarios.splice(Number(button.dataset.index),1);render();}
 }catch(err){showError(err);}
});
main.addEventListener('keydown',e=>{if(e.target.id==='dropzone'&&['Enter',' '].includes(e.key)){e.preventDefault();if(!state.busy)document.querySelector('#csv-files').click();}});
for(const event of ['dragenter','dragover'])main.addEventListener(event,e=>{const z=e.target.closest('#dropzone');if(z){e.preventDefault();z.classList.add('dragover');}});
main.addEventListener('dragleave',e=>e.target.closest('#dropzone')?.classList.remove('dragover'));
main.addEventListener('drop',async e=>{const z=e.target.closest('#dropzone');if(!z)return;e.preventDefault();z.classList.remove('dragover');try{await uploadFiles([...e.dataTransfer.files]);}catch(err){showError(err);}});
window.addEventListener('hashchange',()=>{state.route=routeFromHash();state.error=null;render();window.scrollTo(0,0);});
document.querySelector('#active-twin').addEventListener('change',async e=>{try{await selectTwin(e.target.value);}catch(err){showError(err);}});
async function resumeJob(job){
 const mode=job.request?.mode;state.busy={id:job.id,mode,label:mode?MODES[mode].name:'금융 Twin 생성'};
 if(mode){state.requests[mode]={horizon_days:90,paths:400,seed:42,...clone(job.request)};state.raw[mode]=pretty(job.request);state.editors[mode]='json';}
 render();
 try{const done=await waitJob(job.id);if(done.result){if(mode){const t=state.twins.find(t=>t.id===job.record_id);state.outputs[mode]={result:done.result,request:job.request,recordId:job.record_id,twinName:t?.name||'복구된 작업',elapsed:done.job.elapsed_seconds};}else{state.build.result=done.result;await refreshTwins();state.activeId=done.job.twin.id;state.active=await api('/api/twins/'+state.activeId);localStorage.setItem('keyfin_active_twin',state.activeId);}toast('진행 중이던 작업의 결과를 복구했습니다.');}}
 catch(e){state.error=errorMessage(e);}finally{state.busy=null;render();}
}
async function start(){try{state.config=await api('/api/config');for(const [key,value] of Object.entries(state.config.templates))state.requests[key]=clone(value);await refreshTwins();const saved=localStorage.getItem('keyfin_active_twin');if(saved&&state.twins.some(t=>t.id===saved)){state.active=await api('/api/twins/'+saved);state.activeId=saved;}else if(state.twins.length){state.activeId=state.twins[0].id;state.active=await api('/api/twins/'+state.activeId);}state.route=routeFromHash();render();document.querySelector('#server-status').innerHTML='<span class="dot"></span> ENGINE ONLINE';const activity=await api('/api/activity');if(activity.job)void resumeJob(activity.job);}catch(e){main.innerHTML=`<div class="startup"><h1>엔진에 연결할 수 없습니다.</h1><p>${esc(errorMessage(e))}</p><p>START.bat를 실행하고 표시된 로컬 주소로 접속하세요.</p><button class="btn primary spaced" id="retry-start">다시 연결</button></div>`;document.querySelector('#retry-start')?.addEventListener('click',()=>location.reload());document.querySelector('#server-status').textContent='OFFLINE';}}
await start();
